<?php use Illuminate\Support\Facades\Route;use App\Http\Controllers\{AuthController,DashboardController,TenantSwitchController,ResourceController,CalendarController};
Route::get('/login',[AuthController::class,'show'])->name('login');Route::post('/login',[AuthController::class,'login']);Route::post('/logout',[AuthController::class,'logout'])->name('logout');
Route::middleware('auth')->group(function(){Route::get('/',DashboardController::class)->name('dashboard');Route::post('/tenant-switch',TenantSwitchController::class)->name('tenant.switch');Route::get('/calendar',[CalendarController::class,'index'])->name('calendar.index');Route::get('/calendar/events',[CalendarController::class,'events'])->name('calendar.events');Route::patch('/calendar/campaigns/{campaign}',[CalendarController::class,'move'])->name('calendar.move');Route::post('/campaigns/{campaign}/performance',[ResourceController::class,'performance'])->name('campaigns.performance');Route::resource('topics',ResourceController::class);Route::resource('assets',ResourceController::class);Route::resource('campaigns',ResourceController::class);Route::resource('signal-checks',ResourceController::class);Route::resource('settings/tenants',ResourceController::class)->names('settings.tenants');Route::resource('settings/channels',ResourceController::class)->names('settings.channels');Route::resource('settings/competitors',ResourceController::class)->names('settings.competitors');Route::resource('settings/benchmarks',ResourceController::class)->names('settings.benchmarks');});
